from typing import List

import pytest
from hypothesis import given
import hypothesis.strategies as st

from solution import parse_nested_parens


def ref_max_depth(group: str) -> int:
    depth = 0
    best = 0
    for c in group:
        if c == "(":
            depth += 1
            if depth > best:
                best = depth
        else:
            depth -= 1
    return best


def ref(paren_string: str) -> List[int]:
    # Obviously-correct model: split on single-space separator,
    # ignoring empty tokens produced by leading/trailing/repeated spaces.
    groups = [g for g in paren_string.split(" ") if g != ""]
    return [ref_max_depth(g) for g in groups]


# Small pool of known-balanced groups with known depths.
BALANCED_POOL = ["()", "(())", "(()())", "((()))", "((())()())", "()()", "(()(()))", "(((())))"]
BALANCED_DEPTHS = [1, 2, 2, 3, 3, 1, 3, 4]

balanced_group_strategy = st.sampled_from(BALANCED_POOL)
group_list_strategy = st.lists(balanced_group_strategy, min_size=0, max_size=6)


def test_spec_example():
    assert parse_nested_parens("(()()) ((())) () ((())()())") == [2, 3, 1, 3]


def test_spec_eg_two_levels():
    assert parse_nested_parens("(()())") == [2]


def test_spec_eg_three_levels():
    assert parse_nested_parens("((()))") == [3]


def test_single_empty_parens():
    assert parse_nested_parens("()") == [1]


def test_empty_string_has_no_groups():
    assert parse_nested_parens("") == []


def test_single_space_has_no_groups():
    assert parse_nested_parens(" ") == []


def test_whitespace_only_has_no_groups():
    assert parse_nested_parens("   ") == []


def test_leading_trailing_spaces_ignored():
    assert parse_nested_parens(" (()()) ") == [2]
    assert parse_nested_parens("  ((()))  ") == [3]
    assert parse_nested_parens(" () ") == [1]


def test_consecutive_spaces_ignored():
    assert parse_nested_parens("(()())  ((()))") == [2, 3]
    assert parse_nested_parens("()   ()   ()") == [1, 1, 1]
    assert parse_nested_parens("(()()) ((())) () ((())()())") == parse_nested_parens(
        "(()())  ((()))  ()  ((())()())"
    )


def test_output_length_equals_number_of_groups():
    assert len(parse_nested_parens("() (()) ((()))")) == 3
    assert len(parse_nested_parens("()")) == 1
    assert len(parse_nested_parens("")) == 0


@given(st.lists(st.sampled_from(BALANCED_POOL), min_size=0, max_size=6))
def test_reference_model_equivalence_single_spaces(groups):
    s = " ".join(groups)
    assert parse_nested_parens(s) == ref(s) == [ref_max_depth(g) for g in groups]


@given(st.lists(st.sampled_from(BALANCED_POOL), min_size=0, max_size=5))
def test_extra_spaces_do_not_change_result(groups):
    if not groups:
        return
    single = " ".join(groups)
    double = "  ".join(groups)
    padded = "  " + single + "   "
    assert parse_nested_parens(double) == parse_nested_parens(single)
    assert parse_nested_parens(padded) == parse_nested_parens(single)


@given(st.lists(st.sampled_from(BALANCED_POOL), min_size=1, max_size=5))
def test_concatenation_split(groups):
    # Splitting the group list at any point and joining with a space
    # must equal concatenation of results.
    for k in range(1, len(groups)):
        left = " ".join(groups[:k])
        right = " ".join(groups[k:])
        whole = " ".join(groups)
        assert parse_nested_parens(whole) == parse_nested_parens(left) + parse_nested_parens(right)


@given(st.integers(min_value=1, max_value=10))
def test_deep_nesting_parens(depth):
    s = "(" * depth + ")" * depth
    assert parse_nested_parens(s) == [depth]


@given(st.integers(min_value=1, max_value=10))
def test_repeated_shallow_parens(depth):
    # () repeated n times has depth 1 regardless of n
    s = "()" * depth
    assert parse_nested_parens(s) == [1]


@given(group_list_strategy)
def test_depth_bounds_and_per_group_independence(groups):
    s = " ".join(groups)
    result = parse_nested_parens(s)
    assert len(result) == len(groups)
    for g, d in zip(groups, result):
        assert 1 <= d <= len(g) // 2
        assert d == ref_max_depth(g)
    # Permuting groups permutes results identically.
    rev = list(reversed(groups))
    assert parse_nested_parens(" ".join(rev)) == list(reversed(result))
